SELECT n.nome, n.telefone, n.endereco, n.obs
FROM novos n
WHERE NOT EXISTS (
  SELECT 1 FROM cliente c
  WHERE c.deleted_at IS NULL
    AND LENGTH(COALESCE(n.tel_norm, '')) >= 8
    AND regexp_replace(COALESCE(c.telefone, ''), '\D', '', 'g') = n.tel_norm
);

